\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'FAIL accepted %',q;end$$;
create function pg_temp.session_hash(n integer default 1) returns text language sql volatile as $$select encode(sha256(convert_to('detailing-payment-fixture:'||txid_current()::text||':'||pg_backend_pid()::text||':'||n::text,'UTF8')),'hex')$$;
insert into auth.users(id,email) values('69000000-0000-4000-8000-000000000001','detail-payment-sql-owner@example.test');
select public.create_staging_business('69000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000002','Detailing requests','detail-payment-sql','UTC','USD','AUTO_DETAILING','detail-request-business-sql-001');
select public.create_auto_detailing_offer('69000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000004','{"name":"Detail menu","description":"","currency":"USD","durationMinutes":60,"packages":[{"id":"basic","label":"Basic","amount":15000}],"vehicles":[{"id":"suv","label":"SUV","multiplierBp":12500}],"addons":[{"id":"pet-hair","name":"Pet hair","amount":3000}],"locations":[{"id":"mobile","label":"Mobile","amount":2000}],"idempotencyKey":"detail-request-offer-sql-001"}');
select public.create_auto_detailing_offer_scheduling('69000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000004','UTC','[{"weekday":1,"startMinute":540,"endMinute":1020,"capacity":1}]',0,30,30,'detail-request-schedule-sql-001');
select public.save_detailing_draft('69000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000003','69000000-0000-4000-8000-000000000004',0,'Detail requests','#4f46e5','stacked');
select public.publish_detailing_draft('69000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000003',1,'69000000-0000-4000-8000-000000000005','69000000-0000-4000-8000-000000000006','["https://checkout.example.test"]');
select public.issue_detailing_flow_session('69000000-0000-4000-8000-000000000006',pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]');
create function pg_temp.choice() returns jsonb language sql as $$select '{"packageId":"basic","vehicleId":"suv","addonIds":["pet-hair"],"locationId":"mobile"}'::jsonb$$;
create function pg_temp.customer() returns jsonb language sql as $$select '{"name":"SQL fictional","email":"detail-request-fictional@example.test"}'::jsonb$$;
create function pg_temp.start_at() returns timestamptz language sql as $$select date_trunc('day',now())+interval '1 day 9 hours'$$;
create function pg_temp.model() returns jsonb language sql security definer set search_path=pg_catalog as $$select lumin.detailing_request_model(service_snapshot,pg_temp.choice(),pg_temp.customer(),pg_temp.start_at()) from public.bound_flow_versions where tenant_id='69000000-0000-4000-8000-000000000002' and flow_id='69000000-0000-4000-8000-000000000003' and version_id='69000000-0000-4000-8000-000000000005'$$;
create function pg_temp.request(k text default 'detail-request-operation-sql-001',c jsonb default pg_temp.choice(),price jsonb default pg_temp.model()->'pricing') returns jsonb language sql as $$select public.submit_detailing_reservation(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]',k,c,pg_temp.customer(),pg_temp.start_at(),price)$$;
select pg_temp.assert((select prosecdef and proconfig=array['search_path=pg_catalog'] from pg_proc where oid='public.detailing_payment_target(text,text,jsonb)'::regprocedure),'fixed private payment definer');
select pg_temp.assert(has_function_privilege('service_role','public.detailing_payment_target(text,text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.detailing_payment_target(text,text,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.detailing_payment_target(text,text,jsonb)','EXECUTE'),'server-only payment target');
set local role anon;select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'42501');reset role;
set local role authenticated;select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'42501');reset role;
set local role service_role;select pg_temp.request();
select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'40001');reset role;
create function pg_temp.booking() returns uuid language sql security definer set search_path=pg_catalog as $$select booking_id from public.flow_requests where tenant_id='69000000-0000-4000-8000-000000000002' and session_id=(select id from public.flow_sessions where token_hash=pg_temp.session_hash())$$;
select public.reserve_capacity('69000000-0000-4000-8000-000000000002','69000000-0000-4000-8000-000000000004',pg_temp.start_at(),pg_temp.start_at()+interval '60 minutes',pg_temp.booking(),1,interval '5 minutes');
set local role service_role;select pg_temp.assert(public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')#>>'{booking,state}'='draft','live hold exact draft provenance');reset role;
update public.capacity_holds set expires_at=clock_timestamp()-interval '1 second' where booking_id=pg_temp.booking();
select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'40001');
update public.capacity_holds set expires_at=clock_timestamp()+interval '5 minutes' where booking_id=pg_temp.booking();
insert into public.payments(tenant_id,booking_id,provider,provider_intent_id,state,amount,currency) values('69000000-0000-4000-8000-000000000002',pg_temp.booking(),'staging_mock','staging_mock:'||pg_temp.booking()::text,'succeeded',25000,'USD');
update public.bookings set payment_id=(select id from public.payments where booking_id=pg_temp.booking()) where id=pg_temp.booking();
select public.confirm_succeeded_payment((select id from public.payments where booking_id=pg_temp.booking()));
select pg_temp.assert(public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')#>>'{booking,state}'='confirmed','confirmed replay survives draft transition');
select pg_temp.assert((select status='consumed' from public.capacity_holds where booking_id=pg_temp.booking()),'canonical authority consumed hold');
select pg_temp.assert((select count(*)=1 from public.payments where tenant_id='69000000-0000-4000-8000-000000000002'),'one immutable payment');
select pg_temp.reject($q$select public.detailing_reservation_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'P0002');
select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://foreign.example.test','["https://checkout.example.test"]')$q$,'42501');
update public.payments set amount=1 where booking_id=pg_temp.booking();
select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'40001');
update public.payments set amount=25000 where booking_id=pg_temp.booking();
update public.flow_sessions set expires_at=clock_timestamp()-interval '1 second' where token_hash=pg_temp.session_hash();
select pg_temp.reject($q$select public.detailing_payment_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'42501');
rollback;
